-- Phase 4: Advanced Triggers for Career Engine\n-- Triggers for automatic grade recalculation and commission management\n\n-- Trigger: Update performance metrics when grades change\nCREATE OR REPLACE FUNCTION update_performance_metrics()\nRETURNS TRIGGER AS $$\nBEGIN\n  IF NEW.current_grade != OLD.current_grade THEN\n    -- Log grade upgrade event\n    INSERT INTO audit_logs (\n      user_id,\n      action,\n      description,\n      metadata\n    ) VALUES (\n      NEW.id,\n      'grade_upgraded',\n      CONCAT('Grade changed from ', OLD.current_grade, ' to ', NEW.current_grade),\n      jsonb_build_object(\n        'old_grade', OLD.current_grade,\n        'new_grade', NEW.current_grade,\n        'points', NEW.points\n      )\n    );\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\nCREATE TRIGGER on_grade_change\nAFTER UPDATE OF current_grade ON profiles\nFOR EACH ROW\nWHEN (OLD.current_grade IS DISTINCT FROM NEW.current_grade)\nEXECUTE FUNCTION update_performance_metrics();\n\n-- Trigger: Auto-generate session vouchers on grade upgrade\nCREATE OR REPLACE FUNCTION generate_vouchers_on_upgrade()\nRETURNS TRIGGER AS $$\nDECLARE\n  voucher_count INTEGER;\nBEGIN\n  IF NEW.current_grade != OLD.current_grade THEN\n    -- Get number of vouchers for new grade from grades table\n    SELECT voucher_bonus INTO voucher_count\n    FROM grades\n    WHERE grade_name = NEW.current_grade;\n\n    -- Generate vouchers if applicable\n    IF voucher_count > 0 THEN\n      FOR i IN 1..voucher_count LOOP\n        INSERT INTO session_vouchers (\n          user_id,\n          code,\n          value_fcfa,\n          created_at\n        ) VALUES (\n          NEW.id,\n          generate_referral_code(),\n          3000,\n          NOW()\n        );\n      END LOOP;\n    END IF;\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\nCREATE TRIGGER on_grade_upgrade_vouchers\nAFTER UPDATE OF current_grade ON profiles\nFOR EACH ROW\nWHEN (OLD.current_grade IS DISTINCT FROM NEW.current_grade)\nEXECUTE FUNCTION generate_vouchers_on_upgrade();\n\n-- Trigger: Update team statistics on referral changes\nCREATE OR REPLACE FUNCTION update_team_stats()\nRETURNS TRIGGER AS $$\nBEGIN\n  IF TG_OP = 'INSERT' THEN\n    UPDATE profiles\n    SET updated_at = NOW()\n    WHERE id = NEW.sponsor_id;\n  ELSIF TG_OP = 'DELETE' THEN\n    UPDATE profiles\n    SET updated_at = NOW()\n    WHERE id = OLD.sponsor_id;\n  END IF;\n  RETURN NULL;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\nCREATE TRIGGER on_referral_team_update\nAFTER INSERT OR DELETE ON referrals\nFOR EACH ROW\nEXECUTE FUNCTION update_team_stats();\n\n-- Trigger: Monthly commission batch processing\nCREATE OR REPLACE FUNCTION process_monthly_commissions()\nRETURNS void AS $$\nDECLARE\n  v_user_id UUID;\n  v_commission DECIMAL;\n  v_grade grades%ROWTYPE;\nBEGIN\n  -- Process commissions for all active users\n  FOR v_user_id IN\n    SELECT DISTINCT sponsor_id FROM referrals WHERE verified = TRUE\n  LOOP\n    -- Get user's current grade\n    SELECT g.* INTO v_grade\n    FROM profiles p\n    JOIN grades g ON p.current_grade = g.grade_name\n    WHERE p.id = v_user_id;\n\n    -- Calculate commission for this user\n    SELECT COALESCE(SUM(\n      CASE\n        WHEN generation = 1 THEN amount * (v_grade.commission_rate / 100.0)\n        WHEN generation <= 5 THEN amount * ((v_grade.commission_rate / 100.0) * 0.5)\n        ELSE 0\n      END\n    ), 0) INTO v_commission\n    FROM (\n      SELECT amount, 1 as generation\n      FROM referrals r\n      WHERE r.sponsor_id = v_user_id AND r.verified = TRUE\n      \n      UNION ALL\n      \n      SELECT amount, generation + 1\n      FROM referrals r\n      WHERE r.sponsor_id IN (\n        SELECT referrer_id FROM referrals WHERE sponsor_id = v_user_id AND verified = TRUE\n      )\n    ) sub;\n\n    -- Record commission if > 0\n    IF v_commission > 0 THEN\n      INSERT INTO transactions (\n        user_id,\n        type,\n        status,\n        amount,\n        description\n      ) VALUES (\n        v_user_id,\n        'commission',\n        'completed',\n        v_commission,\n        'Commission mensuelle - ' || TO_CHAR(NOW(), 'Month YYYY')\n      );\n    END IF;\n  END LOOP;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\n-- Function to be called monthly via cron or external scheduler\n-- SELECT process_monthly_commissions();\n"
